CREATE TABLE P360_ORDERS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, VERSION NUMBER(19), RESERVATION_ID VARCHAR2(80), OWNER_ID VARCHAR2(250) NOT NULL, DELETED BOOLEAN NOT NULL, STORE_ID NUMBER(19) NOT NULL, CUSTOMER_NAME VARCHAR2(120) NOT NULL, CUSTOMER_EMAIL VARCHAR2(150) NOT NULL, DELIVERY_ADDRESS VARCHAR2(250), NOTES VARCHAR2(1000), STATUS VARCHAR2(30) NOT NULL, TOTAL NUMBER(12,2), CREATED_AT TIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP, ACCEPTED_AT TIMESTAMP, DISPATCHED_AT TIMESTAMP, DELIVERED_AT TIMESTAMP);
CREATE TABLE P360_ORDER_ITEMS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ORDER_ID NUMBER(19) NOT NULL REFERENCES P360_ORDERS(ID), PRODUCT_ID NUMBER(19) NOT NULL, QUANTITY INTEGER NOT NULL CHECK(QUANTITY>0), UNIT_PRICE NUMBER(12,2) NOT NULL CHECK(UNIT_PRICE>=0));
CREATE INDEX IDX_ORDER_OWNER ON P360_ORDERS(OWNER_ID);
CREATE INDEX IDX_ORDER_STORE ON P360_ORDERS(STORE_ID);
CREATE TABLE P360_OPERATORS (ACTOR_ID VARCHAR2(250) PRIMARY KEY, STORE_ID NUMBER(19) NOT NULL);
CREATE TABLE P360_AUDIT (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ORDER_ID NUMBER(19) NOT NULL, ACTOR_ID VARCHAR2(250) NOT NULL, ACTION VARCHAR2(40) NOT NULL, PREVIOUS_STATUS VARCHAR2(30), STATUS VARCHAR2(30) NOT NULL, STORE_ID NUMBER(19) NOT NULL, OCCURRED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CORRELATION_ID VARCHAR2(64));
CREATE TABLE P360_OUTBOX (ID VARCHAR2(36) PRIMARY KEY, ROUTING_KEY VARCHAR2(40) NOT NULL, PAYLOAD CLOB NOT NULL, ATTEMPTS INTEGER NOT NULL, CREATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, NEXT_ATTEMPT TIMESTAMP WITH TIME ZONE NOT NULL, PUBLISHED_AT TIMESTAMP WITH TIME ZONE, LAST_ERROR VARCHAR2(200));
CREATE INDEX IDX_OUTBOX_PENDING ON P360_OUTBOX(PUBLISHED_AT,NEXT_ATTEMPT);
